#!/usr/bin/env python3
"""Color Wars bot runner. Do not edit this file; your strategy lives in strategy.py.

  python3 bot.py --login         join with the Miro token in .env (MIRO_TOKEN=...); saves your player key
  python3 bot.py --login KEY     or save a player key the instructor gave you
  python3 bot.py --check         read your match from the server and confirm the connection
  python3 bot.py --practice      in TESTING: send one practice move and confirm it is accepted
  python3 bot.py --phase         read the phase once and print it
  python3 bot.py --watch         keep .sdlc/arena-phase.json fresh until you press Ctrl-C
  python3 bot.py --submit        upload your strategy files for the round robin
  python3 bot.py --dry-run       practice arena: checks and a 1-minute game against the house bot
  python3 bot.py                 wait for LIVE, then play until the match ends

The key comes from the PLAYER_KEY environment variable, or from a line PLAYER_KEY=... in the
file .env beside this script. The runner never prints it. Add --server URL to any command to
use another server, for example the local test server in tools/fake_server.py.

The runner sends one move per turn to the game server, which checks it against the rules.
It also keeps three small files in the folder .sdlc: the match phase, the file hashes recorded
before the match, and a log of every run and every move.

Lines that start with KIT-ERROR or KIT-WARN report a problem the runner survived:
  KIT-ERROR choose raised: <Type>: <message>     the first legal square was taken instead
  KIT-WARN illegal square: <square>              the first legal square was taken instead
  KIT-WARN reverted: <square>                    the server refused the move
  KIT-ERROR http <status> <GET|POST>             the server refused a request
  KIT-WARN http 429                              the server asked the runner to slow down
  KIT-ERROR match already live, not starting     see "start guard" in main()
"""
import argparse, hashlib, json, os, sys, time, urllib.error, urllib.parse, urllib.request
from datetime import datetime, timezone

from colorwars import COLS, ROWS, legal_squares, safe_choose

HERE = os.path.dirname(os.path.abspath(__file__))
SDLC = os.path.join(HERE, ".sdlc")
PHASE_FILE = os.path.join(SDLC, "arena-phase.json")
HASH_FILE = os.path.join(SDLC, "arena-hashes.json")
RUN_LOG = os.path.join(SDLC, "arena-run.log")
ENV_FILE = os.path.join(HERE, ".env")
BEFORE_LIVE = ("lobby", "build", "testing")
MAX_AGE = 15 * 60                                      # seconds; the AI-lock plugin ignores older phase files
SERVER_PHASES = {"lobby": "lobby", "build": "build", "testing": "testing", "paused": "paused",
                 "live": "competition", "rr": "competition", "over": "ended", "ended": "ended",
                 "window": "build"}                    # WINDOW: strategy updates, AI tools open again
KIT_FILES = ("bot.py", "simulate.py", "colorwars.py")    # never uploaded: the server has its own
SKIP_DIRS = {".git", ".sdlc", ".venv", "venv", "env", "__pycache__", "tools", "node_modules"}


def warn_python():
    if sys.version_info[:2] != (3, 12):
        v = ".".join(map(str, sys.version_info[:3]))
        print(f"warning: this is Python {v}; the arena runs Python 3.12. Test with 3.12 before you upload.",
              file=sys.stderr, flush=True)


def now():
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def utc(ts):
    return datetime.fromtimestamp(ts, timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def to_epoch(value):
    """Seconds since 1970 from a number or an ISO text such as 2026-11-22T10:00:00Z; None if neither."""
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return float(value)
    if isinstance(value, str) and value:
        try:
            t = datetime.fromisoformat(value.replace("Z", "+00:00"))
            return (t if t.tzinfo else t.replace(tzinfo=timezone.utc)).timestamp()
        except ValueError:
            return None
    return None


def phase_of(banner):
    """Map the server's banner text to a phase name."""
    if "WINS" in banner or "GAME OVER" in banner:
        return "ended"
    if "LIVE" in banner:
        return "competition"
    if "PAUSED" in banner:
        return "paused"
    if "join now" in banner:
        return "lobby"
    if "BUILD" in banner:
        return "build"
    if "TESTING" in banner:
        return "testing"
    return "unknown"


def phase_from(info):
    """The phase-file name for a server answer: its phase field first, then its banner."""
    raw = str(info.get("phase") or "").lower()
    return SERVER_PHASES.get(raw) or phase_of(info.get("banner") or "")


def lock_phase(info, phase):
    """The name written to the phase file: the practice arena plays LIVE but says ai_locked false."""
    if info.get("ai_locked") is False and phase in ("competition", "paused"):
        return "practice"                              # not a lock phase for the plugin
    return phase


def write_json(path, value):
    os.makedirs(SDLC, exist_ok=True)
    tmp = f"{path}.{os.getpid()}.tmp"
    with open(tmp, "w") as f:
        json.dump(value, f)
    os.replace(tmp, path)                              # atomic: a reader never sees half a file


def read_json(path):
    try:
        with open(path) as f:
            return json.load(f)
    except (OSError, ValueError):
        return None


def log_run(line):
    os.makedirs(SDLC, exist_ok=True)
    with open(RUN_LOG, "a") as f:
        f.write(line + "\n")


def file_hashes(config_path):
    paths = {"strategy.py": os.path.join(HERE, "strategy.py"), "config.json": config_path,
             "bot.py": os.path.join(HERE, "bot.py"), "colorwars.py": os.path.join(HERE, "colorwars.py")}
    out = {}
    for label, path in paths.items():
        with open(path, "rb") as f:
            out[label] = hashlib.sha256(f.read()).hexdigest()
    return out


def load_env(name):
    """name from the environment, else from a line name=... in .env beside this script."""
    value = os.environ.get(name, "").strip()
    if value:
        return value
    try:
        with open(ENV_FILE) as f:
            for line in f:
                line = line.strip()
                if line.startswith("export "):
                    line = line[7:].strip()
                if line.startswith(name + "="):
                    return line.split("=", 1)[1].strip().strip("\"'")
    except OSError:
        pass
    return ""


def load_key():
    return load_env("PLAYER_KEY")


def plugin_group():
    """The course plugin's group (A or B) on this computer, or None. Read from the Claude Code settings that hold
    the sdlc plugin's options, then from the plugin's saved state. Never printed: the student does not see it."""
    home = os.path.expanduser("~")
    claude = os.environ.get("CLAUDE_CONFIG_DIR") or os.path.join(home, ".claude")
    files = [os.path.join(claude, "settings.json"),
             "/Library/Application Support/ClaudeCode/managed-settings.json", "/etc/claude-code/managed-settings.json",
             r"C:\Program Files\ClaudeCode\managed-settings.json"]
    for d in ("/Library/Application Support/ClaudeCode/managed-settings.d", "/etc/claude-code/managed-settings.d"):
        if os.path.isdir(d):
            files += [os.path.join(d, f) for f in sorted(os.listdir(d)) if f.endswith(".json")]
    for path in files:
        try:
            with open(path) as f:
                configs = json.load(f).get("pluginConfigs") or {}
        except (OSError, ValueError, AttributeError):
            continue
        for name, conf in configs.items():
            arm = ((conf or {}).get("options") or {}).get("setup") if name.startswith("sdlc@") else None
            if arm in ("A", "B"):
                return arm
    found = []                                         # the plugin's saved session config: {"arm": "A", ...}
    data = os.path.join(claude, "plugins", "data")
    for root, _dirs, names in os.walk(data) if os.path.isdir(data) else ():
        if "sdlc" not in os.path.relpath(root, data).split(os.sep)[0]:
            continue
        for n in names:
            path = os.path.join(root, n)
            try:
                if n.endswith(".json") and os.path.getsize(path) < 1_000_000:
                    with open(path) as f:
                        arm = json.load(f).get("arm")
                    if arm in ("A", "B"):
                        found.append((os.path.getmtime(path), arm))
            except (OSError, ValueError, AttributeError):
                continue
    return max(found)[1] if found else None


def join_with_miro(config_path, server=None):
    """Send the Miro token to the game server (and the practice arena), save the player key it returns."""
    token = load_env("MIRO_TOKEN")
    if not token:
        sys.exit("Put your Miro token in .env first: a line MIRO_TOKEN=... (BRIEF.md, Join the game).")
    cfg = load_config(config_path, server)
    try:
        body = {"miro_token": token, "group": plugin_group()}
        res = Server(cfg["server_url"], "").call("POST", "/cw/join", body, auth=False, tries=3,
                                                 quiet=(400, 401, 403, 404, 409))
    except HttpError as e:
        sys.exit(f"join failed: {e.detail or e}")
    except RuntimeError as e:
        sys.exit(f"join failed: {e}")
    save_key(res["key"])
    practice = cfg.get("practice_url", "")
    if practice.startswith(("http://", "https://")) and practice.rstrip("/") != cfg["server_url"].rstrip("/"):
        try:                                           # same key there; the game still works if this fails
            Server(practice, "").call("POST", "/cw/join", body, auth=False, tries=2,
                                      quiet=(400, 401, 403, 404, 409))
        except RuntimeError as e:
            print(f"warning: the practice arena did not register you ({e}); --dry-run may fail", file=sys.stderr)
    print(f"joined as {res.get('name') or res['alias']} | your name on the dashboard: {res['alias']}")
    print("player key saved in .env. Next: python3 bot.py --check")
    print("watch your match:", my_page(cfg, res["alias"]))


def save_key(key):
    """Write PLAYER_KEY=key into .env, replacing an old PLAYER_KEY line and keeping the others."""
    lines = []
    try:
        with open(ENV_FILE) as f:
            lines = [l.rstrip("\n") for l in f if not l.strip().removeprefix("export ").startswith("PLAYER_KEY=")]
    except OSError:
        pass
    lines.append(f"PLAYER_KEY={key}")
    with open(ENV_FILE, "w") as f:
        f.write("\n".join(lines) + "\n")
    try:
        os.chmod(ENV_FILE, 0o600)
    except OSError:
        pass


def upload_files():
    """{relative path: text} of every .py file except the kit's own, plus requirements.txt."""
    out = {}
    for root, dirs, files in os.walk(HERE):
        dirs[:] = sorted(d for d in dirs if d not in SKIP_DIRS and not d.startswith("."))
        for f in sorted(files):
            rel = os.path.relpath(os.path.join(root, f), HERE).replace(os.sep, "/")
            if rel in KIT_FILES or not (f.endswith(".py") or rel == "requirements.txt"):
                continue
            with open(os.path.join(root, f), encoding="utf-8") as fh:
                out[rel] = fh.read()
    return out


class HttpError(RuntimeError):
    def __init__(self, code, method, path, detail):
        super().__init__(f"HTTP {code} on {method} {path}" + (f": {detail}" if detail else ""))
        self.code, self.detail = code, detail


class Server:
    def __init__(self, url, key):
        self.url = url.rstrip("/")
        self.key = key
        self.skew = 0.0                                # server clock minus this laptop's clock, seconds

    def call(self, method, path, body=None, auth=True, tries=5, quiet=()):
        data = json.dumps(body).encode() if body is not None else None
        for attempt in range(tries):
            headers = {"Content-Type": "application/json", "Accept": "application/json"}
            if auth:
                headers["X-Player-Key"] = self.key
            req = urllib.request.Request(self.url + path, data=data, method=method, headers=headers)
            try:
                sent = time.time()
                with urllib.request.urlopen(req, timeout=15) as r:
                    out = json.loads(r.read() or b"{}")
                server_time = to_epoch(out.get("server_time")) if isinstance(out, dict) else None
                if server_time:                        # midpoint of the request: half the delay each way
                    self.skew = server_time - (sent + time.time()) / 2
                return out
            except urllib.error.HTTPError as e:
                if e.code == 429:                      # too many requests: back off, retry
                    print("KIT-WARN http 429", flush=True)
                    time.sleep(1.5 * (attempt + 1))
                    continue
                if e.code not in quiet:                 # quiet: codes the caller handles as normal
                    print(f"KIT-ERROR http {e.code} {method}", flush=True)
                try:
                    err = json.loads(e.read() or b"{}")
                    detail = str(err.get("detail") or err.get("error") or "") if isinstance(err, dict) else ""
                except ValueError:
                    detail = ""
                raise HttpError(e.code, method, path, detail[:300])
            except (urllib.error.URLError, TimeoutError, ConnectionError):
                time.sleep(1.0 * (attempt + 1))        # network hiccup: retry
        raise RuntimeError(f"the server did not answer after {tries} tries")

    def phase(self):                                   # few tries: --watch reads again in 5 s anyway
        return self.call("GET", "/cw/phase", auth=False, tries=2)

    def state(self):
        return self.call("GET", "/cw/state")

    def move(self, square, hashes):
        return self.call("POST", "/cw/move", {"square": square, "client_ts": time.time(), "hashes": hashes},
                         quiet=(403,))                  # 403: laptop play is over, the uploaded strategy plays

    def submit(self, files):
        return self.call("POST", "/cw/submission", {"files": files})

    def dryrun(self, files):
        return self.call("POST", "/cw/dryrun", {"files": files})

    def local_ends(self, info):
        """The server's ends_at on this laptop's clock, as UTC text, or None."""
        ends = to_epoch(info.get("ends_at"))
        return utc(ends - self.skew) if ends else None


class PhaseFile:
    """Writes .sdlc/arena-phase.json each time the server's phase is read."""

    def __init__(self, board_id):
        self.board, self.ends_at, self.misses = board_id, None, 0
        last = read_json(PHASE_FILE) or {}
        same = last.get("board") == board_id
        self.phase = last.get("phase", "unknown") if same else "unknown"
        self.banner = last.get("banner", "") if same else ""
        self.read_at = last.get("read_at") if same else None
        self.ends_at = last.get("ends_at") if same else None   # an expired lock must stay expired

    def stale(self):
        """The last good read is too old to keep a lock alive: its ends_at passed, or it is older than MAX_AGE."""
        ends, read = to_epoch(self.ends_at), to_epoch(self.read_at)
        return (ends is not None and time.time() > ends + 60) or read is None or time.time() - read > MAX_AGE

    def update(self, phase=None, banner="", ends_at=None):
        """phase is the phase just read, or None when the read failed."""
        if phase is None and self.phase in ("competition", "paused") and self.stale():
            self.phase, self.banner, self.ends_at = "unknown", "", None   # do not bring an old lock back
        if phase is not None:
            # one read with no clear phase must not turn a live match into "unknown"
            if phase == "unknown" and self.phase in ("competition", "paused") and self.misses < 1:
                self.misses += 1
            else:
                self.phase, self.banner, self.read_at, self.misses = phase, banner, now(), 0
                self.ends_at = ends_at
        value = {"phase": self.phase, "banner": self.banner, "read_at": self.read_at,
                 "written_at": now(), "board": self.board}
        if self.ends_at:
            value["ends_at"] = self.ends_at
        try:
            write_json(PHASE_FILE, value)
        except OSError:
            pass                                       # a full disk must not end the match
        return self.phase


def load_config(path, server=None):
    cfg = json.load(open(path))
    if server:
        cfg["server_url"] = cfg["practice_url"] = server
    if not cfg.get("server_url", "").startswith(("http://", "https://")):
        sys.exit("config.json: set \"server_url\" to the game server's address.")
    cfg["interval"] = max(1.0, float(cfg.get("interval", 1.0)))
    cfg["refresh_every"] = max(1, int(cfg.get("refresh_every", 1)))
    return cfg


def my_page(cfg, alias):
    """Full dashboard link to the page that follows this player's match, or a short hint without dashboard_url."""
    dash = cfg.get("dashboard_url", "")
    if dash.startswith(("http://", "https://")):
        return f"{dash.rstrip('/')}/me.html?player={alias}"
    return f"/me?player={alias} on the dashboard"


def print_checks(checks):
    if isinstance(checks, dict):
        for k, v in checks.items():
            print(f"check {k}: {v}")
    elif isinstance(checks, list):
        for c in checks:
            print("check", c if not isinstance(c, dict) else " ".join(f"{k}={v}" for k, v in c.items()))


def main():
    ap = argparse.ArgumentParser(description="Color Wars bot runner")
    ap.add_argument("--config", default=os.path.join(HERE, "config.json"))
    ap.add_argument("--server", help="use this server address instead of server_url in config.json")
    ap.add_argument("--login", metavar="KEY", nargs="?", const="",
                    help="join with MIRO_TOKEN from .env, or save the player KEY you were given, then exit")
    ap.add_argument("--check", action="store_true", help="read your match, print what the bot sees, and exit")
    ap.add_argument("--practice", action="store_true", help="in TESTING: send one practice move and exit")
    ap.add_argument("--phase", action="store_true", help="read the phase once, print it, and exit")
    ap.add_argument("--watch", action="store_true", help="keep .sdlc/arena-phase.json fresh until Ctrl-C")
    ap.add_argument("--submit", action="store_true", help="upload your strategy files and exit")
    ap.add_argument("--dry-run", action="store_true", help="practice arena: checks and a 1-minute game")
    a = ap.parse_args()
    if not (a.login is not None or a.phase or a.watch):            # the warning matters only where the strategy runs
        warn_python()

    if a.login is not None:
        key = a.login.strip()
        if not key:
            return join_with_miro(a.config, a.server)
        if not key.startswith("cwk_"):
            print("warning: a player key starts with cwk_; check that you copied all of it", file=sys.stderr)
        save_key(key)
        print("key saved in .env. Next: python3 bot.py --check")
        return

    cfg = load_config(a.config, a.server)
    url = cfg["server_url"]
    if a.dry_run:
        url = cfg.get("practice_url", "")
        if not url.startswith(("http://", "https://")):
            sys.exit("config.json: set \"practice_url\" to the practice arena's address.")
    key = load_key()
    needs_key = not (a.phase or a.watch)
    if needs_key and not key:
        sys.exit("Set your player key first: python3 bot.py --login cwk_...")

    server = Server(url, key)
    arena = urllib.parse.urlparse(server.url).netloc or server.url
    phase_file = PhaseFile(arena)
    one_shot = a.check or a.practice or a.phase

    def saw(info):
        """Record a server read: the phase file, and the file hashes while the match has not begun."""
        if info is None:
            return phase_file.update(None)
        phase = phase_from(info)
        phase_file.update(lock_phase(info, phase), info.get("banner") or "", server.local_ends(info))
        if phase in BEFORE_LIVE:
            try:
                write_json(HASH_FILE, {"recorded_at": now(), "board": arena, "phase": phase,
                                       "files": file_hashes(a.config)})
            except OSError:
                pass
        return phase

    def read_state():                                  # during a match a failed read is retried, never fatal
        while True:
            try:
                state = server.state()
                saw(state)
                return state
            except RuntimeError as e:
                saw(None)
                if one_shot:
                    sys.exit(f"cannot read the server: {e}")
                print(f"server read failed ({e}); trying again", flush=True)
                time.sleep(2)

    if a.phase:
        try:
            info = server.phase()
        except RuntimeError as e:
            saw(None)
            sys.exit(f"cannot read the phase: {e}")
        saw(info)
        print("phase:", phase_file.phase)
        print("banner:", info.get("banner") or "(none)")
        if phase_file.ends_at:
            print("ends at:", phase_file.ends_at)
        return

    if a.watch:
        print(f"watching {server.url}; press Ctrl-C to stop", flush=True)
        shown = None
        try:
            while True:
                try:
                    info = server.phase()
                    phase = saw(info)
                    if (phase, info.get("banner")) != shown:
                        print(f"{now()} phase: {phase_file.phase} | {info.get('banner') or ''}", flush=True)
                        shown = (phase, info.get("banner"))
                except RuntimeError as e:
                    saw(None)                          # keeps the last phase; moves written_at only
                    print(f"phase read failed ({e}); keeping {phase_file.phase}", flush=True)
                time.sleep(5)
        except KeyboardInterrupt:
            print("watch stopped")
            return

    if a.submit or a.dry_run:
        files = upload_files()
        if "strategy.py" not in files:
            sys.exit("strategy.py is missing: nothing to upload.")
        print("uploading:", " ".join(files))
        extra = [f for f in files if f not in ("strategy.py", "requirements.txt")]
        if extra:
            print("note: these files are uploaded too:", " ".join(extra),
                  "- move backups and scratch files out of this folder if strategy.py does not need them")
        try:
            res = server.submit(files)
        except RuntimeError as e:
            sys.exit(f"upload failed: {e}")
        print("version:", res.get("version"), "| status:", res.get("status"))
        print_checks(res.get("checks"))
        if res.get("status") != "ok":
            sys.exit(f"upload refused: {res.get('error') or res.get('status')}. The last good upload stays.")
        if not a.dry_run:
            print("upload passed")
            return
        try:
            res = server.dryrun({})                    # the server uses the upload that just passed
        except RuntimeError as e:
            sys.exit(f"dry run failed: {e}")
        print_checks(res.get("checks"))
        print("practice game:", res.get("practice_id"))
        print("watch it live:", res.get("live_url"))
        return

    try:
        from strategy import choose
    except Exception as e:
        sys.exit(f"strategy.py does not load: {e}")

    state = read_state()

    def mine_of(st):
        board = st.get("board") or {}
        return board, st.get("color") or "", list(st.get("base") or []), list(st.get("targets") or [])

    board, color, base, targets = mine_of(state)

    if a.check or a.practice:
        print("connected")
        print("server:", server.url, "| phase:", phase_file.phase, "| banner:", state.get("banner") or "(none)")
        if not board or not base:
            print("no match yet: your color and crystal arrive with your match")
            if a.practice:
                sys.exit(f"practice failed: no match board yet (phase {phase_file.phase}). Practice works in TESTING.")
            return
        if state.get("alias"):
            print("your name on the dashboard:", state["alias"])
            print("watch your match:", my_page(cfg, state["alias"]))
        print("your color:", color, "| squares you own:", sum(v == "me" for v in board.values()))
        print("your crystal:", " ".join(base), "| opponent's crystal:", " ".join(targets))
        print("squares on the board:", len(board), "of", COLS * ROWS)
        legal = legal_squares(board, base)
        print("legal squares right now:", len(legal))
        if not a.practice:
            return
        if not legal:
            sys.exit("practice failed: no legal square.")
        square = legal[0]
        try:
            res = server.move(square, file_hashes(a.config))
        except RuntimeError as e:
            sys.exit(f"practice failed: could not send {square}: {e}")
        log_run(f"paint {square} {now()} practice")
        if not res.get("accepted"):
            print(f"KIT-WARN reverted: {square}")
            sys.exit(f"practice failed: {square} refused ({res.get('rule')}: {res.get('reason')})")
        time.sleep(1)
        board = mine_of(read_state())[0]
        if board.get(square) != "me":
            print(f"KIT-WARN reverted: {square}")
            sys.exit(f"practice failed: {square} did not keep your color.")
        print(f"practice passed: {square} is yours")
        return

    # ---- match mode
    hashes = file_hashes(a.config)
    start = f"KIT-START pid={os.getpid()} at={now()} " + " ".join(f"{k}={v}" for k, v in hashes.items())
    print(start, flush=True)
    log_run(start)

    # start guard: a bot may start after LIVE only with the files that were here before LIVE
    phase = phase_from(state)
    if phase == "ended":
        print("KIT-ERROR match already over, not starting")
        sys.exit(f"The match is already over: {state.get('banner')}")
    if phase == "competition":
        record = read_json(HASH_FILE) or {}
        if record.get("board") != arena or record.get("files") != hashes:
            print("KIT-ERROR match already live, not starting")
            sys.exit("The match is live, and strategy.py, config.json, bot.py or colorwars.py differ from the "
                     "copies recorded before it began (or no copy was recorded). A changed bot cannot join.")
        print(f"the match is live; files are the ones recorded at {record.get('recorded_at')}; joining", flush=True)

    shown = None
    while phase_from(state) != "competition" or not state.get("board"):
        if phase_from(state) == "ended":
            print("The match is already over:", state.get("banner"))
            return
        if state.get("banner") != shown:               # print each new banner once, not every poll
            print("waiting:", state.get("banner") or "(no banner)", flush=True)
            shown = state.get("banner")
        time.sleep(2)
        state = read_state()

    board, color, base, targets = mine_of(state)
    if state.get("alias"):
        print("watch your match:", my_page(cfg, state["alias"]), flush=True)
    side = lambda owner: "me" if owner == color else "empty" if owner == "empty" else "enemy"
    turns, since_read, reverted, last_move, last_read = 0, 0, [], 0.0, time.time()
    while True:
        if since_read >= cfg["refresh_every"] or time.time() - last_read > 10:
            state = read_state()
            board, color, base, targets = mine_of(state)
            reverted, since_read, last_read = [], 0, time.time()   # refused since the last read
        phase = phase_from(state)
        if phase == "paused":
            time.sleep(3)
            since_read = cfg["refresh_every"]
            continue
        if phase != "competition" or not board:
            print("Match over:", state.get("banner"))
            return
        legal = legal_squares(board, base)
        pick = safe_choose(choose, board, legal, base, targets, reverted)
        since_read += 1
        if pick is None:
            if not legal:
                print("no legal square; reading the board again", flush=True)
                since_read = cfg["refresh_every"]
            time.sleep(cfg["interval"])
            continue
        wait = cfg["interval"] - (time.time() - last_move)
        if wait > 0:
            time.sleep(wait)
        try:
            res = server.move(pick, hashes)
        except HttpError as e:
            if e.code == 403:                          # round robin: the uploaded strategy plays now
                print(f"Laptop play is over: {e.detail or e}", flush=True)
                return
            print(f"move {pick} failed ({e}); reading the board again", flush=True)
            since_read = cfg["refresh_every"]
            continue
        except RuntimeError as e:                      # one failed move must not end the match
            print(f"move {pick} failed ({e}); reading the board again", flush=True)
            since_read = cfg["refresh_every"]
            continue
        last_move = time.time()                        # timed from the answer, so the server's 1 s rule holds
        try:
            log_run(f"paint {pick} {now()}")
        except OSError:
            pass
        if res.get("rule") == "finished":                # crystal taken: the server keeps LIVE until the end time
            print("Match over: the server says the match is finished", flush=True)
            return
        if not res.get("accepted"):
            print(f"KIT-WARN reverted: {pick}", flush=True)
            print(f"  refused: {res.get('rule')}: {res.get('reason')}", flush=True)
            reverted.append(pick)
            if res.get("rule") != "cooldown":          # the board may be out of date: read it again
                since_read = cfg["refresh_every"]
            continue
        for label, owner in res.get("changed") or []:  # the server says exactly what changed
            if label in board:
                board[label] = side(owner)
        board[pick] = "me"
        turns += 1
        print(f"{turns:4d} {pick}", flush=True)


if __name__ == "__main__":
    main()
